properties.query:
let windowSize = 4h;

// S68: CI/CD Pipeline Compromise — UAVDevOps_CL엔 SwarmId 없음, 전역 게이트
let S68Time = toscalar(
    UAVDevOps_CL
    | where TimeGenerated > ago(windowSize)
    | where UnauthorizedTrigger == true
    | summarize min(TimeGenerated));

// S33: Firmware Tamper — UAVPgse_CL엔 SwarmId 없음(UAVId만), 전역 게이트
let S33Time = toscalar(
    UAVPgse_CL
    | where TimeGenerated > ago(windowSize)
    | where HashMatch == false or Passed == false
    | summarize min(TimeGenerated));

// S101: Leader Hijack — UAVFleetState_CL, FleetId 사용
let S101 =
    UAVFleetState_CL
    | where TimeGenerated > ago(windowSize)
    | where UnknownUavIdDetected == true
    | extend Stage = 'S101', SwarmId = tostring(FleetId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

// S107: 1:N Command Amplification
let S107 =
    UAVFleetState_CL
    | where TimeGenerated > ago(windowSize)
    | where isnotempty(CommonCommand) and ActiveUAVCount > 3
    | extend Stage = 'S107', SwarmId = tostring(FleetId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

union S101, S107
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by SwarmId
| extend HasS68 = isnotnull(S68Time), HasS33 = isnotnull(S33Time)
| extend EffectiveStageCount = StageCount + toint(HasS68) + toint(HasS33)
| where EffectiveStageCount >= 3
| extend CampaignType = "C27_공급망전파_CICD_백도어_리더장악_전군집전파"
| extend StepSummary = strcat("S68(전역)@", tostring(S68Time), " | S33(전역)@", tostring(S33Time), " | Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, SwarmId, StagesSeen, EffectiveStageCount, CampaignType, StepSummary, Severity
